(()=>{
  'use strict';
  const client=window.getFitConnectSupabase?.();
  const $=selector=>document.querySelector(selector);
  const money=value=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'}).format(Number(value||0));
  const decimal=value=>new Intl.NumberFormat('nl-NL',{minimumFractionDigits:1,maximumFractionDigits:1}).format(Number(value||0));
  const safe=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  let requestToken=0;

  function styles(){if($('#dealstudioIntelligenceStyles'))return;const style=document.createElement('style');style.id='dealstudioIntelligenceStyles';style.textContent=`
    .dealstudio-intelligence{margin:0 0 18px;padding:16px;border:1px solid #dedede;border-radius:14px;background:#f8f9fa}.dealstudio-intelligence.loading{opacity:.72}.dealstudio-intelligence-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.dealstudio-intelligence h3{margin:2px 0 4px}.dealstudio-intelligence p{margin:0;color:#5f6368}.dealstudio-health{padding:8px 11px;border-radius:999px;font-weight:800;text-transform:capitalize;background:#eceff1}.dealstudio-health.excellent,.dealstudio-health.healthy{color:#137333;background:#e6f4ea}.dealstudio-health.attention{color:#7a5d00;background:#fff8d8}.dealstudio-health.warning{color:#a14200;background:#fef1e6}.dealstudio-health.critical{color:#b3261e;background:#fce8e6}.dealstudio-metrics{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:9px;margin-top:13px}.dealstudio-metrics article{padding:10px;border-radius:10px;background:#fff;border:1px solid #e7e7e7}.dealstudio-metrics span{display:block;font-size:11px;color:#6b7075}.dealstudio-metrics strong{display:block;margin-top:3px}.dealstudio-alerts{margin:12px 0 0;padding-left:20px;color:#8a2d26}.dealstudio-placeholder{margin-top:10px;padding:10px;border-radius:9px;background:#fff;border:1px dashed #c9cdd2;color:#656a70}@media(max-width:850px){.dealstudio-metrics{grid-template-columns:repeat(2,1fr)}}`;
    document.head.appendChild(style)}

  function panel(){styles();let node=$('#dealstudioIntelligence');if(node)return node;const form=$('#bundleForm');if(!form)return null;node=document.createElement('section');node.id='dealstudioIntelligence';node.className='dealstudio-intelligence';node.innerHTML='<div class="dealstudio-placeholder">Bundle Intelligence wordt geladen zodra deze deal is opgeslagen.</div>';form.prepend(node);return node}

  function warningRows(warnings){const rows=Array.isArray(warnings)?warnings:[];return rows.length?`<ul class="dealstudio-alerts">${rows.map(item=>`<li>${safe(item.message||item.code||'Controle vereist')}</li>`).join('')}</ul>`:''}

  function render(metric){const node=panel();if(!node)return;if(!metric){node.classList.remove('loading');node.innerHTML='<div class="dealstudio-placeholder"><strong>Nog geen berekening beschikbaar.</strong><br>Sla de deal eerst op. Daarna worden kostprijs, brutomarge, capaciteit en healthscore automatisch berekend.</div>';return}node.classList.remove('loading');node.innerHTML=`<div class="dealstudio-intelligence-head"><div><p>Dealstudio · live controle</p><h3>Bundle Intelligence</h3><p>Gebaseerd op actuele verkoopprijzen, inkoopprijzen en voorraad.</p></div><span class="dealstudio-health ${safe(metric.health_status||'critical')}">${safe(metric.health_status||'critical')} · ${Number(metric.health_score||0)}/100</span></div><div class="dealstudio-metrics"><article><span>Brutomarge</span><strong>${money(metric.gross_margin)}</strong></article><article><span>Margepercentage</span><strong>${decimal(metric.gross_margin_percent)}%</strong></article><article><span>Leverbare deals</span><strong>${Number(metric.stock_capacity||0)}</strong></article><article><span>Winstpotentie</span><strong>${money(metric.potential_gross_margin)}</strong></article></div>${warningRows(metric.warnings)}`}

  async function refresh(){const form=$('#bundleForm'),node=panel();if(!client||!form||!node)return;const id=form.elements.id?.value;if(!id){render(null);return}const token=++requestToken;node.classList.add('loading');try{const {data,error}=await client.from('commerce_bundle_intelligence').select('*').eq('bundle_id',id).maybeSingle();if(error)throw error;if(token===requestToken)render(data)}catch(error){if(token!==requestToken)return;node.classList.remove('loading');node.innerHTML=`<div class="dealstudio-placeholder"><strong>Intelligence tijdelijk niet beschikbaar.</strong><br>${safe(error.message||'Onbekende fout')}</div>`}}

  function bind(){const form=$('#bundleForm');if(!form)return;panel();form.addEventListener('input',event=>{if(['bundlePrice','discountAmount','discountPercent'].includes(event.target.name))setTimeout(refresh,250)});const observer=new MutationObserver(refresh);observer.observe($('#bundleEditor')||form,{attributes:true,attributeFilter:['aria-hidden']});document.addEventListener('click',event=>{if(event.target.closest('[data-edit-bundle]')||event.target.closest('#newBundle'))setTimeout(refresh,100)});window.addEventListener('focus',refresh);refresh()}

  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
})();